import { useState } from 'react';

import { ICellRendererParams } from 'ag-grid-community';
import { TextDynamicTruncation } from 'components';

import { COMPETITOR_HEADER } from '../../tableConfig/brandBreakdownConfig';
import { TruncatedBrandName } from './BrandNameCellRenderer.styles';

interface BrandNameCellContentProps {
  brandName: string;
  shouldTruncate: boolean;
  dataTestId?: string;
}

const BrandNameCellContent = ({
  brandName,
  shouldTruncate,
  dataTestId,
}: BrandNameCellContentProps) => {
  const [isTruncated, setIsTruncated] = useState(false);

  return (
    <div
      className={`ag-cell-content${isTruncated ? ' align-left' : ''}`}
      data-testid={dataTestId ? `${dataTestId}-brand-name` : undefined}
    >
      <TextDynamicTruncation
        size="small"
        shouldTruncate={shouldTruncate}
        Component={shouldTruncate ? TruncatedBrandName : undefined}
        dataTestId={
          dataTestId ? `${dataTestId}-brand-name-truncation` : undefined
        }
        onTruncationChange={shouldTruncate ? setIsTruncated : undefined}
      >
        {brandName}
      </TextDynamicTruncation>
    </div>
  );
};

export const BrandNameCellRenderer = (
  params: ICellRendererParams,
  dataTestId?: string,
): JSX.Element => {
  const brandName = String(params.value ?? '');
  const isCompetitorHeader = params.data?.id === COMPETITOR_HEADER;
  const shouldTruncate = !isCompetitorHeader;

  return (
    <BrandNameCellContent
      brandName={brandName}
      shouldTruncate={shouldTruncate}
      dataTestId={dataTestId}
    />
  );
};
